// Messages (docs/09-student-features.qmd): a student's questions to the instructor, with the staff's replies;
// for staff, the inbox across their sections of this package.
import { useEffect, useState } from 'preact/hooks'
import { store, type State } from '../store.ts'
import { sectionName } from '../../../shared/types.ts'
import * as api from '../api.ts'
import type { MarkRow } from '../../../shared/types.ts'
import { whereText, fmtDate } from './PageMarks.tsx'
import { Md } from './Md.tsx'

export function Messages({ s }: { s: State }) {
  const [all, setAll] = useState<MarkRow[] | null>(null)
  const [replies, setReplies] = useState<Record<string, api.Reply[]>>({})
  const [showDone, setShowDone] = useState(false)
  const [err, setErr] = useState<string | null>(null)
  const uid = s.session?.user.id
  const isStaff = s.staffIds.length > 0
  const reload = () => {
    if (!s.pkg || !s.session) return
    api.messages(s.pkg.id).then(async (ms) => {
      setAll(ms)
      const rs = await api.replies(ms.map((m) => m.id))
      const by: Record<string, api.Reply[]> = {}
      for (const r of rs) by[r.mark_id] = [...(by[r.mark_id] || []), r]
      setReplies(by)
    }).catch((e) => setErr(String(e)))
  }
  useEffect(reload, [s.pkg?.id, s.marks.length, s.session?.user.id])
  if (!s.session) return <div class="muted pad">Sign in to message your instructor.</div>
  if (err) return <div class="err">{err}</div>
  if (!all) return <div class="muted pad">Loading…</div>
  const list = all.filter((m) => showDone || m.status === 'open').sort((a, b) => b.created_at.localeCompare(a.created_at))
  const page = s.hello?.page
  return (
    <div class="notes">
      <div class="row">
        <strong>{isStaff ? 'Inbox' : 'My messages'}</strong>
        <label class="chk"><input type="checkbox" checked={showDone} onChange={(e) => setShowDone((e.target as HTMLInputElement).checked)} /> Show resolved</label>
      </div>
      {!isStaff && !s.enrolledIds.length && <div class="warn small">To message your instructor, join your section first: Settings → join code.</div>}
      {!list.length && <div class="muted pad">{isStaff ? 'No open messages.' : 'Select a passage and choose "Ask my instructor" to send one.'}</div>}
      {list.map((m) => (
        <Thread key={m.id} m={m} s={s} replies={replies[m.id] || []} onReplied={reload} isStaff={isStaff} uid={uid} page={page} />
      ))}
    </div>
  )
}

function Thread({ m, s, replies, onReplied, isStaff, uid, page }: { m: MarkRow; s: State; replies: api.Reply[]; onReplied: () => void; isStaff: boolean; uid?: string; page?: string }) {
  const [text, setText] = useState('')
  const send = async () => {
    await store.reply(m, text)
    setText('')
    onReplied()
  }
  const pageTitle = s.build?.toc?.pages?.find((x) => x.page === m.page)?.title || m.page
  const pagePath = s.build?.toc?.pages?.find((x) => x.page === m.page)?.path
  return (
    <div class={`mark k-message ${m.status !== 'open' ? 'done' : ''}`}>
      <div class="mark-head">
        <span class="kind">{String(m.data.topic || 'question')}{m.status !== 'open' ? ' · resolved' : ''}</span>
        <span class="muted small">{fmtDate(m.created_at)}</span>
      </div>
      {m.page === page ? <button class="link where" onClick={() => store.goto(m.id)}>{whereText(m)}</button> : (
        <a class="where" href={pagePath && s.pkg?.site_url ? `${s.pkg.site_url}${pagePath}#yrS4=${m.id}` : '#'} target="_top">{pageTitle}: {whereText(m)}</a>
      )}
      {m.body && <div class="body-md"><Md text={m.body} /></div>}
      {replies.map((r) => (
        <div key={r.id} class="reply small"><strong>{r.author?.display_name || (r.author_id === uid ? 'me' : 'reply')}</strong> · {fmtDate(r.created_at)}<Md text={r.body} /></div>
      ))}
      <div class="row">
        <input placeholder={isStaff ? 'Reply…' : 'Add to the thread…'} value={text} onInput={(e) => setText((e.target as HTMLInputElement).value)} onKeyDown={(e) => { if (e.key === 'Enter') send() }} />
        <button class="small" onClick={send} disabled={!text.trim()}>Send</button>
      </div>
      <div class="actions">
        {(isStaff || m.author_id === uid) && m.status === 'open' && <button class="small" onClick={() => store.setStatus(m, 'done')}>Resolve</button>}
        {isStaff && m.data.topic === 'error-in-book' && <button class="small" onClick={() => store.makeAuthorNote(m)}>Make author note</button>}
        {m.author_id === uid && <button class="small danger" onClick={() => { if (confirm('Delete this message?')) store.remove(m.id).then(onReplied) }}>Delete</button>}
      </div>
    </div>
  )
}
