// Canonical page ids (docs/04-anchoring.qmd): the published path without its extension and version suffix.

const DEFAULT_SUFFIX = '-v\\d{3}'

/** '050100-claudeMd-v001.html' -> '050100-claudeMd'; 'f26/x-v002.html' -> 'f26/x'; 'index.html' -> 'index'. */
export function canonicalPageId(path: string, versionSuffix: string | undefined = DEFAULT_SUFFIX): string {
  let p = path.replace(/^\.?\//, '').replace(/[?#].*$/, '')
  if (p === '' || p.endsWith('/')) p += 'index.html'
  p = p.replace(/\.html?$/i, '')
  if (versionSuffix) {
    try {
      p = p.replace(new RegExp(`(${versionSuffix})$`), '')
    } catch {
      /* a bad pattern in a manifest must not break anything */
    }
  }
  return p
}

/** The path of the current page relative to the book root, given the book's site URL. */
export function pagePathFor(locationHref: string, siteUrl: string | undefined): string {
  const u = new URL(locationHref)
  let path = u.pathname
  if (siteUrl) {
    try {
      const base = new URL(siteUrl).pathname.replace(/\/?$/, '/')
      if (path.startsWith(base)) path = path.slice(base.length)
    } catch {
      /* ignore */
    }
  }
  path = path.replace(/^\//, '')
  if (path === '' || path.endsWith('/')) path += 'index.html'
  return path
}
