// The tutor drawer (docs/08-ai-tutor.qmd): the passage, the action menu, the streamed answer, follow-ups.
import { useEffect, useRef, useState } from 'preact/hooks'
import { store, type State } from '../store.ts'
import { Md } from './Md.tsx'
import { ACTION_LABEL, type TutorAction } from '../../../supabase/functions/_shared/tutor-prompt.ts'

const MENU: TutorAction[] = ['confused', 'simpler', 'example', 'quiz', 'ask']
const ICON: Record<string, string> = { confused: '😕', simpler: '🪜', example: '🧪', quiz: '❓', ask: '✍️', summarize: '📝', remember: '⭐', 'explain-code': '💻', hint: '💡' }

export function Tutor({ s }: { s: State }) {
  const t = s.tutor!
  const [q, setQ] = useState('')
  const bottom = useRef<HTMLDivElement>(null)
  useEffect(() => { bottom.current?.scrollIntoView({ block: 'end' }) }, [t.messages.length, t.streaming])
  const started = t.messages.length > 0
  const menu = t.request.action === 'summarize' ? (['summarize', 'remember'] as TutorAction[]) : t.request.action === 'explain-code' ? (['explain-code', ...MENU] as TutorAction[]) : MENU
  const send = (action: TutorAction, question?: string) => {
    store.askTutor(action, question)
    setQ('')
  }
  return (
    <div class="tutor">
      <div class="editor-head"><strong>✦ About this passage</strong> <button class="link small" onClick={() => store.closeTutor()}>close</button></div>
      {t.request.passage && <div class="quote">{t.request.passage.slice(0, 300)}{t.request.passage.length > 300 ? '…' : ''}</div>}
      {!t.request.passage && <div class="muted small">{t.request.context.headingPath.join(' › ')}</div>}
      {!started && (
        <div class="menu">
          {menu.map((a) => (
            <button key={a} class="small" disabled={t.streaming} onClick={() => (a === 'ask' ? null : send(a))}>{ICON[a]} {ACTION_LABEL[a]}</button>
          ))}
          <div class="row">
            <input placeholder="Ask a specific question…" value={q} onInput={(e) => setQ((e.target as HTMLInputElement).value)} onKeyDown={(e) => { if (e.key === 'Enter' && q.trim()) send('ask', q) }} />
            <button class="small" disabled={!q.trim() || t.streaming} onClick={() => send('ask', q)}>Ask</button>
          </div>
          <button class="link small" onClick={() => store.askInstructorInstead()}>📨 Ask my instructor instead…</button>
        </div>
      )}
      {t.messages.map((m, i) => (
        <div key={i} class={`tmsg ${m.role}`}>{m.role === 'user' ? <div class="small"><strong>You:</strong> {m.content}</div> : <Md text={m.content || '…'} />}</div>
      ))}
      {t.streaming && <div class="muted small">thinking…</div>}
      {t.error && <div class="err small">{t.error}{t.offerStudentKey && <> You can keep going with your own API key (Settings).</>}</div>}
      {started && !t.streaming && (
        <div class="row">
          <input placeholder="Follow up…" value={q} onInput={(e) => setQ((e.target as HTMLInputElement).value)} onKeyDown={(e) => { if (e.key === 'Enter' && q.trim()) send('ask', q) }} />
          <button class="small" disabled={!q.trim()} onClick={() => send('ask', q)}>Send</button>
          {!t.deep && <button class="small" title="Re-ask with a stronger model" onClick={() => store.askTutorDeeper()}>Explain more deeply</button>}
        </div>
      )}
      {t.cost !== undefined && <div class="muted small">cost so far: ${t.cost.toFixed(4)} · {t.model}</div>}
      <div ref={bottom} />
    </div>
  )
}
